const getCurrentLocation = () =>
  typeof window !== 'undefined' && window.location
    ? window.location.href
    : 'https://invalid.local/';

/**
 * Only allow the authenticated WordPress AJAX endpoint generated by Freemius.
 *
 * @param {string} value
 * @param {string} currentLocation
 *
 * @return {string|null}
 */
export function getTrustedRequestHandlerUrl(
  value,
  currentLocation = getCurrentLocation()
) {
  if ('string' !== typeof value || '' === value.trim()) {
    return null;
  }

  try {
    const currentUrl = new URL(currentLocation);
    const requestUrl = new URL(value, currentUrl);

    if (
      !['http:', 'https:'].includes(requestUrl.protocol) ||
      requestUrl.origin !== currentUrl.origin ||
      !/\/wp-admin\/admin-ajax\.php$/.test(requestUrl.pathname) ||
      !requestUrl.searchParams.has('action') ||
      !requestUrl.searchParams.has('security')
    ) {
      return null;
    }

    return requestUrl.toString();
  } catch (error) {
    return null;
  }
}
